// ⚙️ RÉGLAGES : le seul endroit à modifier.
// maitre : le document Arrivées-Départs (annuaire du personnel présent).
// Les Grist « esclaves » ne sont pas listés : n8n prend tous les documents dont le compte de la synchro est PROPRIÉTAIRE
// et qui ont la table Gouv_Utilisateurs avec la case « Ajouté par le maître ». Pour en ajouter un : y installer la colonne
// et donner au compte l'accès propriétaire. exclure : documents à laisser de côté malgré tout (identifiants).
// essai : true = calcule et affiche les changements (nœud « Résumé ») SANS rien écrire.
//         Passer à false après avoir vérifié un premier lancement à la main.
// suppressionsMax : au-delà, on ne supprime personne (une lecture ratée du maître ne vide pas l'annuaire).
// grist : adresse du Grist, pour la recherche des documents (la même que dans l'identifiant « Grist API »).
return [{ json: {
  grist: 'https://grist.numerique.gouv.fr',
  maitre: { nom: 'Arrivées-Départs MOM', docId: '7vFZ964YgDgJ', table: 'Personnel_summary_Courriel' },
  exclure: [],   // ex. ['xxxxxxxxxxxx']
  essai: true,
  suppressionsMax: 10,
} }];

// Agents lus dans l'annuaire du maître (une ligne par agent présent : un agent parti n'y figure plus), mis au format des Grist esclaves.
// Nom affiché : « Prénom NOM » ; entité : le bureau (ex. BSSIOM), sinon la direction (ex. DGOM).
// Un courriel n'apparaît qu'une fois (le premier trouvé), même s'il est écrit avec des majuscules différentes.
const parCourriel = new Map();
for (const { json: f } of $input.all()) {
  if (!f.Courriel) continue;
  const courriel = String(f.Courriel).trim().toLowerCase();
  if (parCourriel.has(courriel)) continue;
  parCourriel.set(courriel, {
    courriel,
    nom: [f.Prenom, f.Nom].filter(Boolean).join(' ').trim(),
    bureau: f.Bureau || '',
    direction: f.Entite || '',
    fonction: f.Fonction || '',
  });
}
const agents = [...parCourriel.values()];
if (!agents.length) throw new Error("Annuaire vide : la synchronisation s'arrête (sécurité : on ne supprime personne sur une lecture ratée).");
return [{ json: { agents } }];

// Tous les documents des espaces lus, où le compte de la synchro est propriétaire (access = owners).
// Sont écartés : le maître, les documents à la corbeille et ceux de la liste « exclure ». Un document vu deux fois ne compte qu'une fois.
const r = $('Réglages').first().json;
const docs = new Map();
for (const { json: espace } of $input.all()) {
  for (const d of espace.docs || []) {   // une organisation illisible donne une erreur sans docs : ignorée
    if (d.access !== 'owners' || d.removedAt) continue;
    if (d.id === r.maitre.docId || r.exclure.includes(d.id) || docs.has(d.id)) continue;
    docs.set(d.id, { nom: d.name, docId: d.id });
  }
}
return [...docs.values()].map((d) => ({ json: d }));

// Ne garde que les Grist de la norme prêts pour la synchro : table Gouv_Utilisateurs avec la case « Ajouté par le maître ».
// (Pas de table : la lecture des colonnes a échoué, le document est ignoré.) Ajoute les agents et les réglages utiles plus loin.
const r = $('Réglages').first().json;
const agents = $('Préparer les agents').first().json.agents;
const docs = $('Documents dont il est propriétaire').all();
return $input.all()
  .map((it, i) => ({ doc: docs[it.pairedItem?.item ?? i].json, colonnes: (it.json.columns || []).map((c) => c.id) }))
  .filter((x) => x.colonnes.includes('Ajoute_par_maitre'))
  .map((x) => ({ json: { ...x.doc, essai: r.essai, suppressionsMax: r.suppressionsMax, agents } }));

// Ce qu'il faut changer dans un Grist esclave (Gouv_Utilisateurs), en comparant au maître par courriel.
// La colonne « Ajouté par le maître » (Ajoute_par_maitre) marque les fiches créées par cette synchro :
// ce sont les SEULES qu'elle met à jour ou supprime. Une personne ajoutée à la main n'est jamais touchée.
// Règles :
//  - agent du maître absent de l'esclave : ajouté (Nom, Courriel, Entité, Fonction, Actif, Ajouté par le maître) ;
//    SANS rôle : il ne voit que l'accueil tant qu'un administrateur de l'application ne lui en a pas donné un ;
//  - fiche marquée d'un agent présent : Nom, Entité et Fonction mis à jour ; le Rôle et la case Actif ne sont JAMAIS touchés ;
//  - fiche marquée d'un agent absent du maître (agent parti) : SUPPRIMÉE ;
//  - fiche non marquée (ajoutée à la main) : rien, même si l'agent est dans le maître.
const cible = $('Cible en cours').first().json;
const entites = $('Lire les entités').all().map((i) => i.json).filter((e) => e.id);   // table vide ou absente : rien (l'entité n'est alors pas remplie)
const users = $input.all().map((i) => i.json).filter((u) => u.id);
const norm = (s) => String(s || '').trim().toLowerCase();
const idEntite = (nom) => (nom ? (entites.find((e) => norm(e.Nom) === norm(nom)) || {}).id : undefined);
const aFonction = users.some((u) => 'Fonction' in u);   // colonne facultative (hors norme)

const parCourriel = new Map(users.map((u) => [norm(u.Courriel), u]));
const ajouts = [], majs = [], suppressions = [];
for (const a of cible.agents) {
  const entite = idEntite(a.bureau) || idEntite(a.direction);   // introuvable : on ne touche pas à l'entité
  const champs = { Nom: a.nom, ...(entite ? { Entite: entite } : {}), ...(aFonction ? { Fonction: a.fonction } : {}) };
  const u = parCourriel.get(a.courriel);
  if (!u) { ajouts.push({ Courriel: a.courriel, Actif: true, Ajoute_par_maitre: true, ...champs }); continue; }
  if (u.Ajoute_par_maitre !== true) continue;   // fiche faite à la main : on n'y touche pas
  const diff = Object.fromEntries(Object.entries(champs).filter(([k, v]) => (u[k] ?? '') !== v));
  if (Object.keys(diff).length) majs.push({ id: u.id, champs: diff });
}
const presents = new Set(cible.agents.map((a) => a.courriel));
const departs = users.filter((u) => u.Ajoute_par_maitre === true && !presents.has(norm(u.Courriel)));
// garde-fou : trop de départs d'un coup = sans doute une lecture incomplète du maître ; on ne supprime personne
const departsBloques = departs.length > cible.suppressionsMax;
if (!departsBloques) for (const u of departs) suppressions.push(u.id);

return [{ json: { nom: cible.nom, docId: cible.docId, essai: cible.essai, ajouts, majs, suppressions,
  resume: `${cible.essai ? '[ESSAI, rien écrit] ' : ''}${cible.nom} : ${ajouts.length} ajout(s), ${majs.length} mise(s) à jour, ${suppressions.length} suppression(s)`
    + (departsBloques ? ` ; ${departs.length} départs NON supprimés (plus de ${cible.suppressionsMax} : vérifier l'annuaire)` : '') } }];

// Une ligne par agent à ajouter (aucune en mode essai). docId sert au nœud suivant et n'est pas écrit dans Grist.
const c = $input.first().json;
return c.essai ? [] : c.ajouts.map((champs) => ({ json: { docId: c.docId, ...champs } }));

// Une ligne par fiche à mettre à jour (aucune en mode essai).
// docId et _ligne servent au nœud suivant et ne sont pas écrits dans Grist.
const c = $input.first().json;
return c.essai ? [] : c.majs.map((m) => ({ json: { docId: c.docId, _ligne: m.id, ...m.champs } }));

// Une ligne par fiche d'agent parti à supprimer (aucune en mode essai). Seules les fiches « Ajouté par le maître » y figurent.
const c = $input.first().json;
return c.essai ? [] : c.suppressions.map((id) => ({ json: { docId: c.docId, _ligne: id } }));
